%{
This MATLAB file is formatted as a function designed to be used with the Bulk Processing application of the MATLAB Image Processing Toolbox. It requires the Bulk Processing application as the inputs (image, imageinfo) are generated by this application. This function is run with Matlab being the primary working drive, and the previously described file structure.
This function under the % INPUTS comment reads a hard-coded reference image to subtract from each image provided by the Bulk Processing feature. It then uniformly crops both images and displays them in a figure. The difference between the images is taken within the RGB color space. The difference image is then converted to grayscale and brightened using imlocalbrighten() to highlight the remaining features and included in the figure. A contrasting function, imadjust() is also applied to the difference image and included in the figure. The brightened image, the difference image, and the composite figure are all written to file in the file structure as PNGs.
%}
%TIC Image Processing
% Function setup to use with Bulk Image Processor
function [result] = TIC_Image_Processing(image, imageinfo)
% SETUP
format long g;
format compact;
fontSize = 20;
clc;
close all;
% INPUT
%The input is the reference image to subtract from the test image.
image1 = imread("TIC/Other/video1_2025_04_02_07_59_59_BST.png"); % SpaceShot
% Crop the images. This crops the TIC collections to the usable pixel area.
image1 = imcrop(image1, [140, 75, 325, 325]);
image2 = imcrop(image, [140, 75, 325, 325]);
% Read Filename
filename = strsplit(imageinfo.Filename, "\");
% Display the images.
nexttile
imshow(image1, []);
axis('on', 'image');
title('Reference Image', 'FontSize', fontSize, 'Interpreter', 'None');
impixelinfo;
hFig = gcf;
hFig.WindowState = 'maximized';

nexttile
imshow(image2, []);
axis('on', 'image');
title('Test Image', 'FontSize', fontSize, 'Interpreter', 'None');
% Take the difference between the images and set to greyscale.
diffImage = imabsdiff(image2, image1);
gsdiff = rgb2gray(diffImage);
% Uniformly brighten the result
bdayLight = imlocalbrighten(diffImage);
nexttile
imshow(bdayLight, []);
% Write brightened image to file
imwrite(bdayLight, "TIC/Brightened/brightened_"+filename(10));
axis('on', 'image');
title('Brightened Image', 'FontSize', fontSize, 'Interpreter', 'None');
% Uniformly adjust the contrast
gsdiff_adjust = imadjust(gsdiff);
% Display the result
nexttile
imshow(gsdiff_adjust, []);
% Write processed result to file.
imwrite(gsdiff_adjust, "TIC/Processed/processed_"+filename(10));
axis('on', 'image');
title('Adjusted Image', 'FontSize', fontSize, 'Interpreter', 'None');
% Write composite figure to file
saveas(gcf, "TIC/Composites/composite_"+filename(10));
result = 1;
end

