%image2 = imread("TIC/Brightened/" + "brightened_" + filename2 + ".png");
% Display the images

nexttile
imshow(image1, []);
axis('on', 'image');
title(filename1, 'FontSize', fontSize, 'Interpreter', 'None');
impixelinfo;
hFig = gcf;
hFig.WindowState = 'maximized';
nexttile
imshow(image2, []);
axis('on', 'image');
title(filename2, 'FontSize', fontSize, 'Interpreter', 'None');
impixelinfo;
% Compute the difference image.
diffImage = imabsdiff(image2, image1);
% Write the difference image to file
imwrite(diffImage, "TIC/"+filename1+"_"+filename2+".png");
% Display the comparison figure
nexttile
imshow(diffImage, []);
axis('on', 'image');
title('Difference Image', 'FontSize', fontSize, 'Interpreter', 'None');
impixelinfo;
% Write the comparison figure to file
saveas(gcf, "TIC/Comparisons/comparison_"+filename1+"_"+filename2+".png");

